528	func proposalViewOf(round uint64, c *candidateState) ProposalView {
529		ids := append([]string(nil), c.TxIDs...)
530		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
531	}
532	
533	// Propose 返回当前轮次唯一的本地提议；重复请求返回同一提议。
534	// 提议生成后即冻结：此后新提交的交易或新登记的候选都不改变该提议，
535	// 提议中的交易禁止替换。其他候选用 RegisterCandidate 另行登记。
536	func (n *Node) Propose() (ProposalView, error) {
537		n.mu.Lock()
538		defer n.mu.Unlock()
539		if rs := n.st.currentRoundState(); rs != nil && rs.LocalBlockID != "" {
540			return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), nil
541		}
542	
543		st := n.st.clone()
544		rs := st.Rounds[st.Round]
545		if rs == nil {
546			rs = &roundState{
547				Round:      st.Round,
548				Height:     uint64(len(st.Blocks)) + 1,
549				PreviousID: st.LastBlock,
550				Candidates: map[string]*candidateState{},
551			}
552			st.Rounds[st.Round] = rs
553		}
554		txIDs := st.selectTransactions()
555		blockID := BlockID(st.Round, rs.Height, rs.PreviousID, txIDs)
556		c := &candidateState{
557			TxIDs:   txIDs,
558			BlockID: blockID,
559			Votes:   []string{},
560			Local:   true,
561		}
562		rs.Candidates[blockID] = c
563		rs.LocalBlockID = blockID
564		for _, id := range txIDs {
565			st.Entries[id].Status = stProposed
566		}
567		if err := n.save(st); err != nil {
568			return ProposalView{}, err
569		}
570		n.st = st
571		return proposalViewOf(rs.Round, c), nil
572	}
