414	// 投票阈值、重复投票、非法投票拒绝。
415	func TestVoting(t *testing.T) {
416		keys := genKeys(t, 4)
417		n, _ := newTestNode(t, keys, 10)
418		p, _ := n.Propose()
419		round := n.CurrentRound()
420	
421		// 名单外身份
422		outsider := genKeys(t, 1)[0]
423		if _, err := n.Vote(outsider.pub, round, p.BlockID); reason(err) != ReasonNotValidator {
424			t.Fatalf("got %v, want %s", err, ReasonNotValidator)
425		}
426		// 错误轮次
427		if _, err := n.Vote(keys[0].pub, round+1, p.BlockID); reason(err) != ReasonWrongRound {
428			t.Fatalf("got %v, want %s", err, ReasonWrongRound)
429		}
430		// 错误区块标识
431		if _, err := n.Vote(keys[0].pub, round, "deadbeef"); reason(err) != ReasonWrongBlock {
432			t.Fatalf("got %v, want %s", err, ReasonWrongBlock)
433		}
434	
435		// 一票
436		res, err := n.Vote(keys[0].pub, round, p.BlockID)
437		if err != nil || !res.Counted || res.Confirmed {
438			t.Fatalf("first vote: %+v %v", res, err)
439		}
440		// 重复投同一票不增加票数
441		res, err = n.Vote(keys[0].pub, round, p.BlockID)
442		if err != nil || res.Counted {
443			t.Fatalf("duplicate vote: %+v %v", res, err)
444		}
445		// 第二票仍不确认（4 人需 3 票）
446		res, _ = n.Vote(keys[1].pub, round, p.BlockID)
447		if res.Confirmed {
448			t.Fatal("2/4 votes must not confirm")
449		}
450		// 第三票确认
451		res, _ = n.Vote(keys[2].pub, round, p.BlockID)
452		if !res.Confirmed {
453			t.Fatal("3/4 votes must confirm")
454		}
455		// 确认后旧轮次投票拒绝（轮次已前进）
456		if _, err := n.Vote(keys[3].pub, round, p.BlockID); reason(err) != ReasonWrongRound {
457			t.Fatalf("stale vote after confirm got %v, want wrong-round", err)
458		}
459	}
