461	// 链连续性：高度、前块标识、交易顺序，且交易查询关联区块。
462	func TestChainContinuity(t *testing.T) {
463		keys := genKeys(t, 4)
464		n, _ := newTestNode(t, keys, 10)
465	
466		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
